mapper.update:
update project
name = #{name}, priority = #{priority}, type = #{type}, pm = #{pmName}, status = #{status}, pm_id = #{pmId}, plan_start_date = #{planStartDate}, plan_end_date = #{planEndDate}, `desc` = #{desc}, modify_man = #{modifyMan}, modify_man_id = #{modifyManId}, actual_start_date = #{actualStartDate}, actual_end_date = #{actualEndDate}
id = #{id}

mapper.select:
select distinct p.id, p.name, p.priority, p.type, p.status, p.pm, p.pm_id, p.plan_start_date, p.plan_end_date, p.actual_start_date, p.actual_end_date, p.`desc`, p.is_deleted, p.create_man_id, p.create_man, p.create_date, p.modify_man_id, p.modify_man, p.modify_date from project_product_demand ppd join project p on ppd.project_id = p.id where ppd.is_deleted = false
and ppd.product_demand_id in
#{item}

select distinct b.project_id from project_product_line b left join product_line c on b.product_line_id=c.id
left join biz_domain d on c.biz_domain_id=d.id
and b.project_id in
#{item}
and b.product_line_id in
#{item}
and d.id in
#{item}
and b.is_deleted=false

select a.id,a.name, a.priority, a.type ,a.status,a.pm_id,a.pm pmName ,a.plan_start_date,a.plan_end_date,
a.actual_start_date,a.actual_end_date,a.`desc`,
a.create_man_id, a.create_man,a.create_date,a.modify_date
from project a


        and a.id in

            #{item}


    and a.id = #{id}
    and a.name like concat('%',#{name},'%')

        and a.plan_start_date >= #{planStartDateLeft} and a.plan_start_date <= #{planStartDateRight}


        and a.plan_end_date >= #{planEndDateLeft} and a.plan_end_date <= #{planEndDateRight}


        and a.actual_start_date >= #{actualStartDateLeft} and a.actual_start_date <= #{actualStartDateRight}


        and a.actual_end_date >= #{actualEndDateLeft} and a.actual_end_date <= #{actualEndDateRight}


        and a.priority in

            #{item}



        and a.status in

            #{item}



        and a.type in

            #{item}



        and a.pm_id in

            #{item}


    and a.is_deleted =false

select id,name, priority, type ,status,pm_id,pm pmName ,plan_start_date,plan_end_date, actual_start_date,actual_end_date,`desc`, create_man_id, create_man,create_date,modify_date from project
id in
#{item}

select pj.id, pj.name, pj.priority, pj.type, pj.status, pj.pm, pj.pm_id, pj.plan_start_date, pj.plan_end_date, pj.actual_start_date, pj.actual_end_date, pj.`desc`, pj.is_deleted, pj.create_man_id, pj.create_man, pj.create_date, pj.modify_man_id, pj.modify_man, pj.modify_date from person p join project pj on pj.id = p.main_id where p.user_id in
#{item}
and p.type < 20 and p.is_deleted = false and pj.is_deleted = false group by pj.id
